function checkpoint(fromEditor=true){if(autosaveTimer!==null){clearTimeout(autosaveTimer);autosaveTimer=null;}if(serviceParsing)return false;if($('#revision-entry-form'))return saveEntry();if(!doc)return true;try{if(fromEditor)capture();const next={...doc,text:revisedText(doc),updatedAt:dirty?now():doc.updatedAt},rows=list(keys.drafts),at=rows.findIndex(d=>String(d.id)===next.id);if(at<0)rows.unshift(next);else rows[at]=next;write(keys.drafts,rows);doc=next;dirty=false;const status=$('#rev-save-state');if(status)status.textContent='草稿已自动保存 · 当前浏览器';return true;}catch{context.notify('草稿保存失败，当前编辑仍保留，请导出备份后重试。');return false;}}
